mapper.select:
SELECT 
FROM user_course_hour_records
WHERE user_id = #{userId}
    AND course_id = #{courseId}
    AND hour_id = #{hourId}
ORDER BY is_finished DESC, finished_at DESC, id DESC
LIMIT 1

SELECT COUNT(DISTINCT hour_id)
FROM user_course_hour_records
WHERE user_id = #{userId}
    AND course_id = #{courseId}
    AND is_finished = 1

SELECT `course_id`, count(1) AS `total`
FROM `user_course_hour_records`
WHERE `user_id` = #{userId}

    AND `course_id` IN (#{courseId})


    AND `is_finished` = #{isFinished}

GROUP BY `course_id`;

SELECT count(1)
FROM `user_course_hour_records` as `t`


        AND `t`.`user_id` = #{userId}


        AND `t`.`is_finished` = #{isFinished}

SELECT `user_id`, count(1) AS `total`
FROM `user_course_hour_records`
WHERE `course_id` = #{courseId}

    AND `user_id` IN (#{userId})


    AND `is_finished` = #{isFinished}

GROUP BY `user_id`;

SELECT `t1`.`created_at`, `t1`.`user_id` FROM `user_course_hour_records` AS `t1` INNER JOIN (SELECT `t2`.`user_id`, min(`t2`.`created_at`) as `created_at` FROM `user_course_hour_records` AS `t2` WHERE `t2`.`course_id` = #{courseId}
AND `t2`.`user_id` IN (#{userId})
GROUP BY `t2`.`user_id`) AS `t3` ON `t3`.`user_id` = `t1`.`user_id` AND `t3`.`created_at` = `t1`.`created_at` WHERE `t1`.`course_id` = #{courseId}
AND `t1`.`user_id` IN (#{userId})

SELECT COUNT(1)
FROM user_course_hour_records AS r
WHERE
    r.user_id = #{userId}
    AND r.is_finished = 1
    AND r.finished_at IS NOT NULL;
